var n=`1099-khao-piak-sen`;var s=`world-1099`;var a=`LA`;var t=`southeast-asia`;var o=4;var r=66;var h={en:`Khao Piak Sen`,ua:`Кхао п'як сен`};var g={en:`Khao Piak Sen is a dish from Laos prepared with chicken thigh, lemongrass, rice noodles, fish sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кхао п'як сен, страва кухні країни Лаос, яку готують із таких продуктів: куряче стегно, лемонграс, рисова локшина, рибний соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 50 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 50 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:50,i:[[`chicken-thigh`,650,`g`],[`chicken-stock`,1300,`ml`],[`ground-ginger`,35,`g`],[`lemongrass`,2,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`rice-noodles`,450,`g`],[`water`,1e3,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,32,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,30,`g`],[`green-onion`,35,`g`]]}];var m={slug:n,id:s,country:`LA`,region:t,servings:4,minutes:66,title:h,text:g,steps:l};export{a as country,m as default,s as id,r as minutes,t as region,o as servings,n as slug,l as steps,g as text,h as title};